// AST definitions.

use std::cell::Cell;
use std::rc::Rc;

pub type P<T> = Box<T>;

/// Scope id assigned by the resolver (u32::MAX = none).
#[derive(Debug)]
pub struct ScopeId(pub Cell<u32>);
impl ScopeId {
    pub fn new() -> ScopeId {
        ScopeId(Cell::new(u32::MAX))
    }
    pub fn get(&self) -> u32 {
        self.0.get()
    }
    pub fn set(&self, v: u32) {
        self.0.set(v)
    }
}
impl Default for ScopeId {
    fn default() -> Self {
        ScopeId::new()
    }
}

#[derive(Debug)]
pub struct Program {
    pub body: Vec<Stmt>,
    pub strict: bool,
    pub is_module: bool,
    pub scope: ScopeId,
    pub source: Rc<str>,
    pub has_top_level_await: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum VarKind {
    Var,
    Let,
    Const,
    Using,
    AwaitUsing,
}

#[derive(Debug)]
pub struct VarDecl {
    pub kind: VarKind,
    pub decls: Vec<VarDeclarator>,
}

#[derive(Debug)]
pub struct VarDeclarator {
    pub target: Pattern,
    pub init: Option<Expr>,
}

#[derive(Debug)]
pub enum Pattern {
    Ident(Ident),
    Object { props: Vec<ObjPatProp>, rest: Option<P<Pattern>> },
    Array { elems: Vec<Option<PatElem>>, rest: Option<P<Pattern>> },
    /// only in assignment patterns: arbitrary member expression target
    Expr(P<Expr>),
}

#[derive(Debug)]
pub struct PatElem {
    pub target: Pattern,
    pub default: Option<Expr>,
}

#[derive(Debug)]
pub struct ObjPatProp {
    pub key: PropKey,
    pub target: Pattern,
    pub default: Option<Expr>,
}

#[derive(Debug, Clone)]
pub struct Ident {
    pub name: Rc<str>,
    pub line: u32,
}

#[derive(Debug)]
pub enum PropKey {
    Ident(Rc<str>),   // identifier or string literal name
    Str(Rc<[u16]>),   // string literal (utf16)
    Num(f64),
    Computed(P<Expr>),
    Private(Rc<str>),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FuncKind {
    Normal,
    Arrow,
    Method,
    Getter,
    Setter,
    ClassConstructor,
    DerivedConstructor,
    ClassFieldInit,
    StaticBlock,
}

#[derive(Debug)]
pub struct Function {
    pub name: Option<Ident>,
    pub params: Vec<Param>,
    pub body: Vec<Stmt>,
    /// arrow with expression body: body contains a single Return statement
    pub expr_body: bool,
    pub kind: FuncKind,
    pub is_async: bool,
    pub is_generator: bool,
    pub strict: bool,
    pub simple_params: bool,
    pub src_start: usize,
    pub src_end: usize,
    pub scope: ScopeId,
    /// scope for the body when parameters have expressions (separate var scope)
    pub body_scope: ScopeId,
    /// is this a function expression (named function expressions bind their own name)
    pub is_expr: bool,
    pub is_decl: bool,
    pub line: u32,
    pub has_use_strict_directive: bool,
}

#[derive(Debug)]
pub struct Param {
    pub pat: Pattern,
    pub default: Option<Expr>,
    pub rest: bool,
}

#[derive(Debug)]
pub struct Class {
    pub name: Option<Ident>,
    pub extends: Option<P<Expr>>,
    pub members: Vec<ClassMember>,
    pub constructor: Option<Rc<Function>>,
    pub src_start: usize,
    pub src_end: usize,
    pub scope: ScopeId,
    pub decorators: Vec<Expr>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MethodKind {
    Method,
    Getter,
    Setter,
}

#[derive(Debug)]
pub enum ClassMember {
    Method { key: PropKey, func: Rc<Function>, kind: MethodKind, is_static: bool },
    Field { key: PropKey, value: Option<Rc<Function>>, is_static: bool, is_accessor: bool },
    StaticBlock(Rc<Function>),
