                            Handler::Native(await_return_rejected, Value::Obj(g.clone())),
                            None,
                        );
                    }
                    Err(e) => {
                        if let ObjKind::AsyncGenerator(ag) = &mut g.borrow_mut().kind {
                            ag.awaiting_return = false;
                        }
