fn once_wrapper(vm: &mut Vm, this: &Value, name: &Value, f: &Value) -> Value {
    let w = vm.native_closure("bound onceWrapper", 0, once_fire, vec![this.clone(), name.clone(), f.clone(), Value::Bool(false)]);
